import{at as e,it as t,n,vt as r}from"./chunks/framework.D9OOHiq-.js";var i=JSON.parse(`{"title":"从 PlayerKits 2 迁移","description":"","frontmatter":{},"headers":[],"relativePath":"modules/kits/migration-playerkits2.md","filePath":"modules/kits/migration-playerkits2.md","lastUpdated":0}`),a={name:`modules/kits/migration-playerkits2.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="从-playerkits-2-迁移" tabindex="-1">从 PlayerKits 2 迁移 <a class="header-anchor" href="#从-playerkits-2-迁移" aria-label="Permalink to “从 PlayerKits 2 迁移”">​</a></h1><p>本页给把 PlayerKits 2 迁到 EmakiKits 的服主. 对照只写有据可依的部分 (依据 PlayerKits 2 资源页与 wiki 目录), 不确定处标注「待确认」</p><h2 id="概念映射" tabindex="-1">概念映射 <a class="header-anchor" href="#概念映射" aria-label="Permalink to “概念映射”">​</a></h2><table tabindex="0"><thead><tr><th>PlayerKits 2</th><th>EmakiKits</th><th>说明</th></tr></thead><tbody><tr><td>kit 定义</td><td><code>kits/*.yml</code></td><td>EmakiKits 一文件一礼包, id 取文件内 <code>id</code> 字段</td></tr><tr><td>Cooldown</td><td>周期礼包 / <code>max_claims_total</code></td><td>PlayerKits 2 是冷却时间 (单位以其文档为准); EmakiKits 用周期键或累计上限近似, 秒级冷却不支持 (待确认)</td></tr><tr><td>One Time</td><td><code>max_claims_total: 1</code></td><td>一次性礼包</td></tr><tr><td>Permission Required</td><td>礼包 <code>permission</code> 字段</td><td>节点改为 <code>emakikits.</code> 前缀并同步权限插件</td></tr><tr><td>Requirements: Price</td><td><code>purchase</code> 段</td><td><code>price</code> / <code>max_purchases</code> / 经济桥选择</td></tr><tr><td>Actions on claim</td><td><code>action</code> 奖励</td><td>EmakiKits 走 CoreLib 动作管道; on error 动作无对应 (待确认)</td></tr><tr><td>First join kit</td><td><code>join</code> 类型礼包</td><td><code>join.on_first_join: true</code></td></tr><tr><td>Kit preview</td><td><code>/ekits preview</code></td><td>不显示权重, 不预测抽取结果</td></tr><tr><td>Kit Edit GUI</td><td><code>/ekits edit</code></td><td>1.0.6 起提供全 GUI 编辑器</td></tr><tr><td>Kit Display Items 四态</td><td>(无对应)</td><td>待确认</td></tr><tr><td>Auto Armor / Auto Offhand</td><td>(无对应)</td><td>待确认</td></tr><tr><td>Inventory.yml 自建菜单</td><td>(无对应)</td><td>EmakiKits 不做自建总览菜单</td></tr><tr><td>MySQL</td><td>(无)</td><td>EmakiKits 仅 <code>data/store.yml</code>; SQLite / MySQL 明确不做 (等全系统一数据库方案)</td></tr></tbody></table><h2 id="命令映射" tabindex="-1">命令映射 <a class="header-anchor" href="#命令映射" aria-label="Permalink to “命令映射”">​</a></h2><table tabindex="0"><thead><tr><th>PlayerKits 2</th><th>EmakiKits</th></tr></thead><tbody><tr><td><code>/kit &lt;kit&gt;</code> 或 <code>/kit claim &lt;kit&gt;</code></td><td><code>/ekits claim &lt;礼包ID&gt;</code></td></tr><tr><td><code>/kit</code> (GUI)</td><td>(无对应总菜单, 待确认)</td></tr><tr><td><code>/kit edit &lt;kit&gt;</code></td><td><code>/ekits edit &lt;礼包ID&gt;</code></td></tr><tr><td><code>/kit create &lt;kit&gt;</code></td><td><code>/ekits edit</code> 浏览器内新建</td></tr><tr><td><code>/kit give &lt;kit&gt; &lt;player&gt;</code></td><td><code>/ekits grant &lt;玩家&gt; &lt;礼包ID&gt;</code> (语义近似: PlayerKits 2 直接发放且忽略条件, EmakiKits <code>grant</code> 是增加一次可领取次数)</td></tr><tr><td><code>/kit delete</code></td><td><code>/ekits edit</code> 内删除</td></tr><tr><td><code>/kit reset ...</code></td><td>(无对应, 待确认)</td></tr></tbody></table><h2 id="数据迁移" tabindex="-1">数据迁移 <a class="header-anchor" href="#数据迁移" aria-label="Permalink to “数据迁移”">​</a></h2><ul><li>EmakiKits 的礼包定义是 <code>plugins/EmakiKits/kits/*.yml</code>, 运行数据是 <code>plugins/EmakiKits/data/store.yml</code>, 与 PlayerKits 2 的配置与数据互不相通</li><li><strong>没有自动导入</strong>: 礼包定义按上表人工改写; PlayerKits 2 的领取 / 冷却记录不导入, 迁移后从空记录开始</li><li>PlayerKits 2 wiki 的 Migrating 章节只覆盖它自己的 v1 升级, 与跨插件迁移无关</li></ul><h2 id="迁移步骤建议" tabindex="-1">迁移步骤建议 <a class="header-anchor" href="#迁移步骤建议" aria-label="Permalink to “迁移步骤建议”">​</a></h2><ol><li>测试服安装 EmakiCoreLib + EmakiKits, 按概念映射表逐个改写礼包定义</li><li><code>/ekits check</code> 确认加载状态, <code>/ekits preview</code> 核对奖励内容</li><li>切换权限节点与命令绑定, 验证领取 / 购买 / 预览</li><li>确认无误后再下线 PlayerKits 2</li></ol>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};